// Agoda — minimum absolute difference pairs (LeetCode 1200), then pairs at an exact difference k (LeetCode 532).
public static class MinAbsDiff {
    // All pairs (a, b), a < b, whose difference equals the minimum difference in the array, ascending.
    public static List<(int A, int B)> MinimumPairs(int[] arr) {
        var res = new List<(int, int)>();
        if (arr == null || arr.Length < 2) return res;
        var s = (int[])arr.Clone();                      // never reorder the caller's array
        Array.Sort(s);
        long best = long.MaxValue;
        for (int i = 1; i < s.Length; i++) {
            long d = (long)s[i] - s[i - 1];
            if (d < best) { best = d; res.Clear(); }
            if (d == best) res.Add((s[i - 1], s[i]));
        }
        return res;
    }

    // Number of UNIQUE value pairs (x, y) with y - x == k, k >= 0.
    public static int CountPairsWithDiff(int[] nums, int k) {
        if (nums == null) return 0;
        if (k < 0) throw new ArgumentOutOfRangeException(nameof(k));
        var freq = new Dictionary<int, int>();
        foreach (var x in nums) freq[x] = freq.GetValueOrDefault(x) + 1;
        int count = 0;
        foreach (var (x, c) in freq) {
            if (k == 0) { if (c > 1) count++; }
            else if (x <= int.MaxValue - k && freq.ContainsKey(x + k)) count++;
        }
        return count;
    }
}
